import { cn } from "@/lib/utils"

/**
 * Total Wireless Savings Bar Component
 *
 * The dual-tone teal bar that displays savings amount and due today price.
 * This is a KEY visual element of the Total Wireless shopping flow.
 *
 * Usage:
 * <SavingsBar
 *   savings={{ label: "You save", value: "$120/yr" }}
 *   dueToday={{ label: "Due today", value: "$55.00" }}
 * />
 */

interface SavingsBarSection {
  label: string
  value: string
}

interface SavingsBarProps extends React.HTMLAttributes<HTMLDivElement> {
  savings: SavingsBarSection
  dueToday: SavingsBarSection
}

function SavingsBar({
  className,
  savings,
  dueToday,
  ...props
}: SavingsBarProps) {
  return (
    <div
      data-slot="savings-bar"
      className={cn(
        "flex rounded-xl overflow-hidden font-sans",
        className
      )}
      {...props}
    >
      {/* Left: Savings (lighter teal) */}
      <div className="flex-1 bg-tw-teal-50 px-4 py-3 text-center text-tw-navy-900">
        <div className="text-[11px] font-medium uppercase tracking-wide opacity-80">
          {savings.label}
        </div>
        <div className="text-xl font-bold tracking-tight">{savings.value}</div>
      </div>

      {/* Right: Due Today (darker teal) */}
      <div className="flex-1 bg-tw-teal-400 px-4 py-3 text-center text-tw-navy-900">
        <div className="text-[11px] font-medium uppercase tracking-wide opacity-80">
          {dueToday.label}
        </div>
        <div className="text-xl font-bold tracking-tight">
          {dueToday.value}
        </div>
      </div>
    </div>
  )
}

export { SavingsBar }
export type { SavingsBarProps, SavingsBarSection }
